const TArray<FWireSegment>& AFoil11111WireframeActor::Segments() { return GSegments; }

AFoil11111WireframeActor::AFoil11111WireframeActor() { PrimaryActorTick.bCanEverTick = true; }

void AFoil11111WireframeActor::Tick(float DeltaSeconds)
{
    Super::Tick(DeltaSeconds);
    const FTransform& X = GetActorTransform();
    for (const FWireSegment& S : GSegments)
    {
        DrawDebugLine(GetWorld(), X.TransformPosition(S.A), X.TransformPosition(S.B),
                      LineColor, false, -1.f, 0, LineThickness);
    }
}
